{
  "path": "/proj/train/AI/workdir/e0031982/eda_sandbox_flow/sessions/default_cline-eval-001_EDA-Eval-DesignFlow-AutoCellTclFlow-001_0/ref/7nm/layer_functions.tcl",
  "content": "# =============================================================================
# AutoCell 7nm (tcbn7) Example - Layer Functions (2/7)
#
# Documents the *semantic role* each CAD layer plays.  In the planar `dram`
# example these roles are applied separately with `tech set_layer_function`.
# The 7nm foundry deck (copied unmodified into library/tech.tcl) instead embeds
# each layer's function *inline* in its `add_layer ... -functions { ... }`
# declaration, which is loaded by layers.tcl - so nothing needs to run here.
# This file is kept to mirror the dram split and to list the roles at a glance.
#
# The major role groups (all declared in layers.tcl):
#   poly / pgate / ngate        -> PO (gate poly over P / N active)
#   nwell / psub                -> NW, PSUB (bodies)
#   nplus / pplus               -> NP / PP (source-drain implants) + VTL_P/VTL_N
#   m1 / m2 / m3                -> M1 / M2 / M3 (+ M1A/M1B, M2A/M2B, M3A/M3B)
#   m0_cut / m1a_cut / m1b_cut  -> CMD / CM1A / CM1B, CPO (poly cut), etc.
#   poly_cont / m0_cont / via   -> VD / VG / V1 / V2 cut layers
#
# See the `-functions` flags in layers.tcl for the full per-layer mapping.
# =============================================================================
# `tech set_layer_function` assigns each CAD layer its *semantic role* (the
# layer *function*).  A bare GDS layer number only identifies a mask; the
# function says what that mask actually does on silicon - e.g. AA/OD is the
# Active Area (diffusion), PO/GC the poly gate, NP/PP the N+/P+ source-drain
# implants, NW/PSUB the well/substrate bodies, VD/VG the contacts and
# V1/V2 the metal vias.  Recognising these roles is what lets AutoCell
# reconstruct transistors and mark pins before extraction, DRC and LVS.
# Terminology follows doc/knowledge/EDA_Standard_Cell_Unified_Glossary.md
# (sections 08/09: 版图层、几何关系与设计规则).
#
tech set_layer_function -layer "prBoundary:boundary" -functions { "border" "psub" }
tech set_layer_function -layer "BCMD" -functions { "butted_m0_cut" }
tech set_layer_function -layer "BVG" -functions {"butted_cont"}
tech set_layer_function -layer "CM1A" -functions { "m1a_cut" }
tech set_layer_function -layer "CM1B" -functions { "m1b_cut" }
tech set_layer_function -layer "CMD" -functions { "m0_cut" }
tech set_layer_function -layer "CPO" -functions { "poly_cut" }
tech set_layer_function -layer "PODE_GATE" -functions { "poly_mask" }
tech set_layer_function -layer "M1" -functions { "m1" }
tech set_layer_function -layer "M1:pin" -functions { "m1_label" }
tech set_layer_function -layer "M1A" -functions { "m1a" }
tech set_layer_function -layer "M1B" -functions { "m1b" }
tech set_layer_function -layer "M2" -functions { "m2" }
tech set_layer_function -layer "M2:pin" -functions { "m2_label" }
tech set_layer_function -layer "M2A" -functions { "m2a" }
tech set_layer_function -layer "M2B" -functions { "m2b" }
tech set_layer_function -layer "M3" -functions { "m3" }
tech set_layer_function -layer "M3:pin" -functions { "m3_label" }
tech set_layer_function -layer "M3A" -functions { "m3a" }
tech set_layer_function -layer "M3B" -functions { "m3b" }
tech set_layer_function -layer "MD" -functions { "m0p" "m0n" }
tech set_layer_function -layer "MP" -functions { "m0g" }
tech set_layer_function -layer "NP" -functions {"nplus"}
tech set_layer_function -layer "NW" -functions { "nwell" }
tech set_layer_function -layer "NW:pin" -functions { "nwell_label" }
tech set_layer_function -layer "OD" -functions { "pdiff" "ndiff" }
tech set_layer_function -layer "PO" -functions { "poly" "pgate" "ngate" }
tech set_layer_function -layer "PP" -functions {"pplus"}
tech set_layer_function -layer "PSUB:pin" -functions { "psub_label" }
tech set_layer_function -layer "VD" -functions { "pcont" "ncont" }
tech set_layer_function -layer "VG" -functions { "poly_cont" }
tech set_layer_function -layer "V1" -functions { "via1" }
tech set_layer_function -layer "V2" -functions { "via2" }

