tech default_tech add_rule -type min_width -layer "MP" -value 0.020
tech default_tech add_rule -type min_width -layer "MD" -value 0.024
tech default_tech add_rule -type min_width -layer "M1" -value 0.020
tech default_tech add_rule -type min_width -layer "M2" -value 0.037
tech default_tech add_rule -type min_width -layer "V1" -value 0.020
tech default_tech add_rule -type min_width -layer "VD" -value 0.016
tech default_tech add_rule -type min_width -layer "VG" -value 0.016
tech default_tech add_rule -type min_width -layer {"CM1A"} -value 0.024
tech default_tech add_rule -type min_width -layer {"CM1B"} -value 0.024
tech default_tech add_rule -type min_spacing -layer {"MD" "MP"} -value 0.018
tech default_tech add_rule -type min_spacing -layer {"MD"} -value 0.018
tech default_tech add_rule -type min_spacing -layer {"M1"} -value 0.020
tech default_tech add_rule -type min_spacing -layer {"M2"} -value 0.020
tech default_tech add_rule -type min_spacing -layer {"CMD"} -value 0.028

#tech default_tech add_rule -type min_area -layer "MD" -value 0.0024
tech default_tech add_rule -type min_area -layer "M1" -value 0.00123
tech default_tech add_rule -type min_area -layer "M2" -value 0.00272

tech default_tech add_rule -type min_via_spacing -layer {"VD" "VG"} -condition_prl 0 -value 0.026

