#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
AutoCell TCL Flow Generator (generic).

Reads a JSON process specification (``spec.json``) and the eight skeleton ``.tcl``
templates, then writes a complete, internally-consistent AutoCell standard-cell
TCL flow into the target output directory:

    run.tcl  layers.tcl  layer_functions.tcl  viadefs.tcl
    globals.tcl  rules.tcl  place.tcl  route.tcl

The generated flow follows the documented pipeline contract:

  * creation order : layers -> layer_functions -> viadefs -> globals -> rules
                     -> place -> route -> run
  * sourcing order : layers, layer_functions, viadefs, globals, rules, place, route
  * ``tech -process`` lives in ``layers.tcl`` (never in ``run.tcl``)
  * via *definitions* live in ``viadefs.tcl``; via *instances* (``via .. -viadef ..``)
    live in ``route.tcl``
  * exactly one placement mode (auto => ``set_placer``, replay => ``read_placement``)
  * predictable GDS output path via ``[file join $case_dir ...]``
  * explicit router contract (``grid_map``, ``pin_template``, ``pin_grid``,
    ``vdd_connector``, ``vss_connector``)

Usage:
    python3 generate_autocell_flow.py \\
        --spec     /path/to/spec_planar.json \\
        --skeleton /path/to/assets/skeleton \\
        --out      /path/to/outputs
"""

import argparse
import json
import os
import re
import sys

__all__ = ["generate_flow", "normalize_spec", "main"]

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

# Technology files, in the order they must be sourced by run.tcl.
SOURCE_ORDER = [
    "layers.tcl",
    "layer_functions.tcl",
    "viadefs.tcl",
    "globals.tcl",
    "rules.tcl",
    "place.tcl",
    "route.tcl",
]

# run.tcl plus the seven technology files.
EIGHT_FILES = ["run.tcl"] + SOURCE_ORDER

# Placeholder schemes recognised in skeleton templates, in addition to a literal
# ``TODO``/``TBD`` marker.  ``<group>`` is a dotted key such as ``layer.gate.name``.
PLACEHOLDER_RE = re.compile(
    r"\{\{\s*(?P<k>[A-Za-z0-9_.\-]+)\s*\}\}"
    r"|@(?P<a>[A-Za-z0-9_.\-]+)@"
    r"|<<\s*(?P<l>[A-Za-z0-9_.\-]+)\s*>>"
    r"|%%(?P<p>[A-Za-z0-9_.\-]+)%%"
    r"|\$\{(?P<d>[A-Za-z0-9_.\-]+)\}"
    r"|###(?P<h>[A-Za-z0-9_.\-]+)###"
)

RESIDUE_RE = re.compile(
    r"TODO|TBD|FIXME|XXX|PLACEHOLDER"
    r"|\{\{\s*[A-Za-z0-9_.\-]+\s*\}\}"
    r"|@[A-Za-z0-9_.\-]+@"
    r"|<<\s*[A-Za-z0-9_.\-]+\s*>>"
    r"|%%[A-Za-z0-9_.\-]+%%"
    r"|\$\{[A-Za-z0-9_.\-]+\}"
    r"|###[A-Za-z0-9_.\-]+###"
)


class FlowError(Exception):
    """Raised when the spec cannot produce a valid flow."""


# ---------------------------------------------------------------------------
# Small formatting helpers
# ---------------------------------------------------------------------------

def _num(v):
    """Render a numeric value the way Tcl users expect (no float noise)."""
    if isinstance(v, bool):
        return "1" if v else "0"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        if v == int(v) and abs(v) < 1e15:
            return str(int(v))
        return repr(v)
    if isinstance(v, str):
        return v.strip()
    return str(v)


def _q(s):
    """Quote a string for Tcl double-quoted context."""
    s = str(s).replace("\\", "\\\\").replace('"', '\\"')
    return '"%s"' % s


def _numlist(values):
    """Tcl brace list of numbers: { 0.07 0.3 }"""
    return "{ %s }" % " ".join(_num(v) for v in values)


def _wordlist(values):
    """Tcl brace list of bare words: { VDD VCC }"""
    return "{ %s }" % " ".join(str(v) for v in values)


def _qlist(values):
    """Tcl brace list of quoted strings: { "pdiff" "ndiff" }"""
    return "{ %s }" % " ".join(_q(v) for v in values)


def _keyval(key, value):
    return "-%s %s" % (key, value)


def _as_list(value):
    if value is None:
        return []
    if isinstance(value, (list, tuple)):
        return list(value)
    return [value]


def _as_str_list(value):
    items = _as_list(value)
    out = []
    for it in items:
        if isinstance(it, str):
            # Allow a single string with space separated tokens.
            out.extend([t for t in it.split() if t])
        else:
            out.append(str(it))
    return out


# ---------------------------------------------------------------------------
# JSON / IO helpers
# ---------------------------------------------------------------------------

def load_json(path):
